export function build(g) {
  // 1. ROSE ARCHES (x=24 and x=34 spanning z=14..16)
  roseArch(g, { x: 24, zA: 14, zB: 16 });
  roseArch(g, { x: 34, zA: 14, zB: 16 });

  // 2. ESPALIERS (fruit trees trained against the walls)
